   550  func expandString(s string, vars map[string]string, visiting map[string]bool) (string, error) {
   551          var b strings.Builder
   552          i := 0
   553          for i < len(s) {
   554                  if i+1 < len(s) && s[i] == '$' && s[i+1] == '{' {
   555                          end := strings.Index(s[i:], "}")
   556                          if end == -1 {
   557                                  return "", fmt.Errorf("unterminated variable reference in %q", s)
   558                          }
   559                          name := s[i+2 : i+end]
   560                          if name == "" {
   561                                  return "", fmt.Errorf("empty variable reference in %q", s)
   562                          }
   563                          if visiting[name] {
   564                                  return "", fmt.Errorf("variable cycle detected: %q", name)
