func (e *buildExecutor) runCommand(t *TargetConfig, command string, env []string, deadline time.Time) (string, error) {
    if strings.TrimSpace(command) == "" {
        return "", nil
    }
    remaining := time.Until(deadline)
    if remaining <= 0 {
        return "", fmt.Errorf("target %q timed out after %ds", t.Name, t.Timeout)
    }
    var stdout, stderr bytes.Buffer
    ctx, cancel := context.WithTimeout(context.Background(), remaining)
    defer cancel()
    cmd := exec.CommandContext(ctx, "sh", "-c", command)
    cmd.Dir = e.configDir
    cmd.Env = env
    cmd.Stdout = &stdout
    cmd.Stderr = &stderr
    cmd.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
    if err := cmd.Start(); err != nil {
        return "", err
    }
    waitCh := make(chan error, 1)
    go func() { waitCh <- cmd.Wait() }()
    select {
    case <-ctx.Done():
        if cmd.Process != nil {
            _ = syscall.Kill(-cmd.Process.Pid, syscall.SIGKILL)
        }
        <-waitCh
        return "", fmt.Errorf("target %q timed out after %ds", t.Name, t.Timeout)
    case err := <-waitCh:
        if err != nil {
            if stderr.Len() > 0 {
                fmt.Fprintf(os.Stderr, "target %q stderr:\n%s", t.Name, stderr.String())
            }
            return "", err
        }
    }
    return stdout.String(), nil
}
